                    table,
                    filter: Some(filter),
                    alias,
                }
            } else {
                Node::Filter { source, predicate }
            }
        } else {
            node
        }
    }
}

/// Uses a hash join instead of a nested loop join for single-column equijoins.
#[derive(Debug)]
pub struct HashJoin;

impl Optimizer for HashJoin {
    fn optimize(&self, node: Node) -> Result<Node> {
        Ok(Self::hash_join(node))
    }
}

impl HashJoin {
    /// Rewrites a nested loop join into a hash join if possible.
    pub fn hash_join(node: Node) -> Node {
        node.transform(
            &|n| Ok(n),
            &|n| match n {
                Node::NestedLoopJoin { left, right, predicate, outer } => {
                    let left = Box::new(Self::hash_join(*left));
                    let right = Box::new(Self::hash_join(*right));

                    // Check if we can convert to hash join
                    if let Some((left_col, right_col)) = Self::find_equijoin_columns(&predicate) {
                        Node::HashJoin {
                            left,
                            left_column: left_col,
                            right,
                            right_column: right_col,
                            outer,
                        }
                    } else {
                        Node::NestedLoopJoin {
                            left,
                            right,
                            predicate,
                            outer,
                        }
                    }
                }
                other => other,
            },
        )
        .unwrap()
    }

    fn find_equijoin_columns(predicate: &Option<Expression>) -> Option<(usize, usize)> {
        if let Some(expr) = predicate {
            // Look for a simple equality join condition
            if let Expression::Equal(l, r) = expr {
                if let (Expression::Column(l_col), Expression::Column(r_col)) = (l.as_ref(), r.as_ref()) {
                    if *l_col != *r_col {
                        return Some((*l_col, *r_col));
                    }
                }
            }
        }
        None
    }
}

/// Short-circuits useless nodes and expressions.
#[derive(Debug)]
pub struct ShortCircuit;

impl Optimizer for ShortCircuit {
    fn optimize(&self, node: Node) -> Result<Node> {
        Ok(Self::short_circuit(node))
    }
}

